<?php foreach ($reports as $r): ?><div class="card"><p><a href="<?= site_url('clubs/' . $this->m_chat_group->group($r['group_id'])['slug']) ?>"><?= e($r['name']) ?></a> · Tin #<?= (int) $r['message_id'] ?></p><p><?= e($r['reason']) ?></p><form method="post" action="<?= site_url('admin/chat_groups/resolve/' . $r['id']) ?>"><input type="hidden" name="chat_csrf" value="<?= e($chat_csrf) ?>"><button class="btn" type="submit">Đánh dấu đã xử lý</button></form></div><?php endforeach; ?>
</section>
<section class="ag-panel"><header class="ag-panel-head"><h2>Nhật ký gần nhất</h2><span><?= count($logs) ?> hoạt động</span></header><div class="table-responsive"><table class="table"><thead><tr><th>Thời gian</th><th>Người xử lý</th><th>Nhóm</th><th>Thao tác</th><th>Đối tượng</th><th>Lý do</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td><?= e($log['created_at']) ?></td><td>#<?= (int) $log['actor_id'] ?></td><td>#<?= (int) $log['group_id'] ?></td><td><?= e($log['action']) ?></td><td><?= e($log['target']) ?></td><td><?= e($log['reason']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$logs): ?><p class="ag-empty">Chưa có hoạt động quản trị.</p><?php endif; ?></section>
